from pulp import *

# Define the problem
problem = LpProblem("WarehouseDistribution", LpMinimize)

# Define sets for warehouses and stores
warehouses = ['A', 'B']
stores = ['X', 'Y', 'Z']

# Define parameters
supply = {'A': 70, 'B': 50}
demand = {'X': 40, 'Y': 30, 'Z': 50}
costs = {
    ('A', 'X'): 2,
    ('A', 'Y'): 3,
    ('A', 'Z'): 4,
    ('B', 'X'): 3,
    ('B', 'Y'): 2,
    ('B', 'Z'): 1
}

# Define decision variables
x = {}
for i in warehouses:
    for j in stores:
        x[i, j] = LpVariable(f'x_{i}_{j}', lowBound=0, cat='Continuous')

# Objective function: Minimize transportation cost
problem += lpSum(costs[i, j] * x[i, j] for i in warehouses for j in stores)

# Supply constraints
for i in warehouses:
    problem += lpSum(x[i, j] for j in stores) <= supply[i]

# Demand constraints
for j in stores:
    problem += lpSum(x[i, j] for i in warehouses) == demand[j]

# Solve the problem
problem.solve()

# Print the optimal solution and objective value
print("Optimal Transportation Plan:")
for i in warehouses:
    for j in stores:
        if x[i, j].value > 0:
            print(f"{x[i, j]} = {x[i, j].value:.2f}")
print(f"Total Minimum Transportation Cost: {problem.objective.value():.2f}")
